'use client'

import type { ComponentProps } from 'react'
import {
  createToggleController,
  createToggleGroupController,
  Toggle as UiToggle,
  ToggleGroup as UiToggleGroup,
  ToggleIcon as UiToggleIcon,
} from '@ui-sdk/react/toggle'
import { createContext, useContext } from 'react'

import './toggle.css'

function omit<T extends object, const K extends readonly (keyof T)[]>(
  obj: T,
  ...keys: K
): Omit<T, K[number]> {
  const copy = { ...obj }
  for (const key of keys) delete copy[key]
  return copy
}

export { createToggleController, createToggleGroupController }

export type {
  ToggleApi,
  ToggleChangeOptions,
  ToggleController,
  ToggleGroupApi,
  ToggleGroupChangeOptions,
  ToggleGroupController,
  ToggleGroupOptions,
  ToggleGroupOrientation,
  ToggleGroupState,
  ToggleGroupValueChangeReason,
  ToggleIconProps,
  ToggleIconState,
  ToggleOptions,
  TogglePressedChangeReason,
  ToggleState,
} from '@ui-sdk/react/toggle'

/**
 * Toggle and ToggleGroup, styled for Kitsaas on top of ui-sdk's headless
 * Toggle primitives.
 *
 * Supports `variant` (`neutral`, `outline`, `ghost`) and `size` (`small`,
 * `normal`, `large`). Inside a `ToggleGroup`, child toggles inherit the
 * group's `variant` (defaulting to `ghost`) and `size` unless overridden.
 */

export type ToggleVariant = 'neutral' | 'outline' | 'ghost'
export type ToggleSize = 'small' | 'normal' | 'large'

interface ToggleGroupStyleContextValue {
  variant: () => ToggleVariant
  size: () => ToggleSize
}

const ToggleGroupStyleContext =
  createContext<ToggleGroupStyleContextValue | null>(null)

type UiToggleProps = ComponentProps<typeof UiToggle>

export type ToggleProps = Omit<UiToggleProps, 'className' | 'render'> & {
  /** Defaults to `neutral` standalone, or inherits from `ToggleGroup` (default `ghost`). */
  variant?: ToggleVariant
  /** Defaults to `normal` (28px), or inherits from `ToggleGroup`. */
  size?: ToggleSize
  className?: UiToggleProps['className']
  render?: UiToggleProps['render']
}

export function Toggle(props: ToggleProps) {
  const groupStyle = useContext(ToggleGroupStyleContext)
  const rest = omit(props, 'variant', 'size', 'className', 'render')

  const variant = () =>
    props.variant ?? (groupStyle ? groupStyle.variant() : 'neutral')
  const size = () =>
    props.size ?? (groupStyle ? groupStyle.size() : 'normal')

  return (
    <UiToggle
      {...rest}
      className={props.className}
      render={props.render}
      data-variant={variant()}
      data-size={size()}
    />
  )
}

type UiToggleIconProps = ComponentProps<typeof UiToggleIcon>

export type ToggleIconPartProps = Omit<UiToggleIconProps, 'className' | 'render'> & {
  className?: UiToggleIconProps['className']
  render?: UiToggleIconProps['render']
}

export function ToggleIcon(props: ToggleIconPartProps) {
  const rest = omit(props, 'className', 'render')

  return <UiToggleIcon {...rest} className={props.className} render={props.render} />
}

type UiToggleGroupProps<T extends string = string> = ComponentProps<
  typeof UiToggleGroup<T>
>

export type ToggleGroupProps<T extends string = string> = Omit<
  UiToggleGroupProps<T>,
  'className' | 'render'
> & {
  /** Shared variant for child toggles. Defaults to `ghost`. */
  variant?: ToggleVariant
  /** Shared size for child toggles. Defaults to `normal`. */
  size?: ToggleSize
  className?: UiToggleGroupProps<T>['className']
  render?: UiToggleGroupProps<T>['render']
}

export function ToggleGroup<T extends string = string>(
  props: ToggleGroupProps<T>,
) {
  const rest = omit(props, 'variant', 'size', 'className', 'render')

  return (
    <ToggleGroupStyleContext.Provider
      value={{
        variant: () => props.variant ?? 'ghost',
        size: () => props.size ?? 'normal',
      }}
    >
      <UiToggleGroup<T>
        {...rest}
        className={props.className}
        render={props.render}
      />
    </ToggleGroupStyleContext.Provider>
  )
}

/*
 * Toggle & ToggleGroup styles for Kitsaas on top of @ui-sdk/solid/toggle.
 *
 * Attribute-driven rules (`data-variant`, `data-size`, `data-pressed`,
 * `data-disabled`, `data-orientation`, `data-mirror`) using semantic `--v2-*`
 * tokens that flip automatically with `[data-color-scheme="dark"]`.
 */

@layer components {
  [data-slot="toggle"] {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    flex-shrink: 0;
    border: 0;
    border-radius: 6px;
    font-family: var(--font-family-sans);
    font-style: normal;
    font-weight: 530;
    font-size: 13px;
    line-height: 20px;
    letter-spacing: -0.04px;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    user-select: none;
    cursor: pointer;
    outline: none;
    transition:
      background-color 100ms ease,
      color 100ms ease,
      box-shadow 100ms ease;
  }

  [data-slot="toggle"]:focus {
    outline: none;
  }

  [data-slot="toggle"]:focus-visible {
    outline: 2px solid var(--v2-border-border-focus);
    outline-offset: 2px;
    z-index: 1;
  }

  [data-slot="toggle"][data-size="small"] {
    height: 24px;
    min-width: 24px;
    padding: 0 8px;
    border-radius: 4px;
  }

  [data-slot="toggle"][data-size="normal"] {
    height: 28px;
    min-width: 28px;
    padding: 0 10px;
    border-radius: 6px;
  }

  [data-slot="toggle"][data-size="large"] {
    height: 32px;
    min-width: 32px;
    padding: 0 12px;
    border-radius: 6px;
  }

  /* Icon-only square sizing */
  [data-slot="toggle"][aria-label]:has(> svg:only-child, > [data-slot="toggle-icon"]:only-child) {
    padding: 0;
  }

  [data-slot="toggle"][data-size="small"][aria-label]:has(> svg:only-child, > [data-slot="toggle-icon"]:only-child) {
    width: 24px;
  }

  [data-slot="toggle"][data-size="normal"][aria-label]:has(> svg:only-child, > [data-slot="toggle-icon"]:only-child) {
    width: 28px;
  }

  [data-slot="toggle"][data-size="large"][aria-label]:has(> svg:only-child, > [data-slot="toggle-icon"]:only-child) {
    width: 32px;
  }

  [data-slot="toggle-icon"] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 16px;
    height: 16px;
    flex-shrink: 0;
    color: currentColor;
  }

  [data-slot="toggle-icon"] > svg {
    width: 16px;
    height: 16px;
    flex-shrink: 0;
  }

  [dir="rtl"] [data-slot="toggle-icon"][data-mirror] {
    transform: scaleX(-1);
  }

  /* Neutral */
  [data-slot="toggle"][data-variant="neutral"] {
    background-color: var(--v2-background-bg-button-neutral);
    color: var(--v2-text-text-muted);
    box-shadow: var(--v2-elevation-button-neutral);
  }

  @media (hover: hover) {
    [data-slot="toggle"][data-variant="neutral"]:hover:not(:disabled, [data-disabled], [data-pressed]) {
      color: var(--v2-text-text-base);
      background-image:
        linear-gradient(90deg, var(--v2-overlay-simple-overlay-hover) 0%, var(--v2-overlay-simple-overlay-hover) 100%),
        linear-gradient(90deg, var(--v2-background-bg-button-neutral) 0%, var(--v2-background-bg-button-neutral) 100%);
    }
  }

  [data-slot="toggle"][data-variant="neutral"]:active:not(:disabled, [data-disabled]) {
    background-image:
      linear-gradient(90deg, var(--v2-overlay-simple-overlay-pressed) 0%, var(--v2-overlay-simple-overlay-pressed) 100%),
      linear-gradient(90deg, var(--v2-background-bg-button-neutral) 0%, var(--v2-background-bg-button-neutral) 100%);
  }

  [data-slot="toggle"][data-variant="neutral"][data-pressed] {
    background-image: none;
    background-color: var(--v2-background-bg-layer-03);
    color: var(--v2-text-text-base);
    box-shadow: inset 0 0 0 0.5px var(--v2-border-border-strong);
  }

  /* Outline */
  [data-slot="toggle"][data-variant="outline"] {
    background-color: transparent;
    color: var(--v2-text-text-muted);
    box-shadow: inset 0 0 0 1px var(--v2-border-border-base);
  }

  @media (hover: hover) {
    [data-slot="toggle"][data-variant="outline"]:hover:not(:disabled, [data-disabled], [data-pressed]) {
      background-color: var(--v2-overlay-simple-overlay-hover);
      color: var(--v2-text-text-base);
    }
  }

  [data-slot="toggle"][data-variant="outline"]:active:not(:disabled, [data-disabled]) {
    background-color: var(--v2-overlay-simple-overlay-pressed);
  }

  [data-slot="toggle"][data-variant="outline"][data-pressed] {
    background-color: var(--v2-background-bg-layer-03);
    color: var(--v2-text-text-base);
    box-shadow: inset 0 0 0 1px var(--v2-border-border-strong);
  }

  /* Ghost */
  [data-slot="toggle"][data-variant="ghost"] {
    background-color: transparent;
    color: var(--v2-text-text-muted);
  }

  @media (hover: hover) {
    [data-slot="toggle"][data-variant="ghost"]:hover:not(:disabled, [data-disabled], [data-pressed]) {
      background-color: var(--v2-overlay-simple-overlay-hover);
      color: var(--v2-text-text-base);
    }
  }

  [data-slot="toggle"][data-variant="ghost"]:active:not(:disabled, [data-disabled]) {
    background-color: var(--v2-overlay-simple-overlay-pressed);
  }

  [data-slot="toggle"][data-variant="ghost"][data-pressed] {
    background-color: var(--v2-background-bg-layer-03);
    color: var(--v2-text-text-base);
  }

  /* Disabled */
  [data-slot="toggle"]:is(:disabled, [data-disabled]) {
    opacity: 0.5;
    cursor: not-allowed;
  }

  /* ToggleGroup */
  [data-slot="toggle-group"] {
    display: inline-flex;
    flex-direction: row;
    align-items: center;
    gap: 2px;
    padding: 2px;
    border-radius: 8px;
    background-color: var(--v2-background-bg-layer-01);
    box-shadow: inset 0 0 0 1px var(--v2-border-border-muted);
  }

  [data-slot="toggle-group"][data-orientation="vertical"] {
    flex-direction: column;
    align-items: stretch;
  }

  [data-slot="toggle-group"] [data-slot="toggle"] {
    border-radius: 5px;
  }

  [data-slot="toggle-group"] [data-slot="toggle"][data-size="small"] {
    border-radius: 4px;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="toggle"] {
      transition: none;
    }
  }
}
